66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /** Dedicated audit logger for owner lifecycle side-effects. */
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    /**
75	     * Pragmatic check for a syntactically valid email address: a non-empty local
76	     * part, a single '@', and a domain with at least one dot-separated label.
77	     */
78	    private static final Pattern EMAIL_PATTERN =
79	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
80	
81	    /**
82	     * Disposable email domains that are rejected: an owner email whose domain is one of
83	     * these is treated as invalid so the create/update is rejected with 400. Compared
84	     * case-insensitively against the normalized (lower-cased) email domain.
85	     */
86	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
87	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
88	
89	    /**
90	     * Common street-type abbreviations expanded during address normalization,
91	     * keyed by their upper-cased form.
92	     */
93	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
94	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
95	
96	    /**
97	     * Required national-number length keyed by E.164 country calling code: a
98	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'}
99	     * (NANP) number carries 10. A number whose country code is listed here must have
100	     * exactly the mandated number of national digits.
101	     */
102	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
103	        Map.of("61", 9, "1", 10);
104	
105	    /**
106	     * Inclusive 4-digit postcode range {@code {low, high}} keyed by the region derived
107	     * from the owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose
108	     * region is not listed here (see {@link OwnerMapper#CITY_REGION}) accepts any 4-digit
109	     * postcode.
110	     */
111	    private static final Map<String, int[]> REGION_POSTCODE_RANGES =
112	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099},
113	            "QLD", new int[] {4000, 4099});
114	
115	    /** HTTP header carrying the client-supplied idempotency key for owner creation. */
116	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
117	
118	    /**
119	     * Remembers the owner created for each seen {@code Idempotency-Key}, so a create that
120	     * repeats with an already-seen key returns the originally created owner (200) instead of
121	     * creating a duplicate. Kept in-memory and keyed by the raw header value.
122	     */
123	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
124	
125	    private final ClinicService clinicService;
126	
127	    private final OwnerMapper ownerMapper;
128	
129	    private final PetMapper petMapper;
130	
131	    private final VisitMapper visitMapper;
