143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
146	        Collection<Owner> owners;
147	        if (lastName != null) {
148	            owners = this.clinicService.findOwnerByLastName(lastName);
149	        } else {
150	            owners = this.clinicService.findAllOwners();
151	        }
152	        if (owners.isEmpty()) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
171	        // Idempotent create: when the request carries an 'Idempotency-Key' already seen on a
172	        // previous successful create, return the originally created owner with 200 instead of
173	        // creating a duplicate.
174	        String idempotencyKey = currentIdempotencyKey();
175	        if (idempotencyKey != null) {
176	            Integer existingId = idempotentCreates.get(idempotencyKey);
177	            if (existingId != null) {
178	                Owner existing = this.clinicService.findOwnerById(existingId);
179	                if (existing != null) {
180	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
181	                }
182	            }
183	        }
184	        // Validate & normalize the optional email; reject the create when it is present but invalid.
185	        if (!normalizeEmail(ownerFieldsDto)) {
186	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
187	        }
188	        // Validate & normalize the optional postcode; reject the create when it is present but
189	        // not valid for the owner's city (see normalizePostcode).
190	        if (!normalizePostcode(ownerFieldsDto)) {
191	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
192	        }
193	        // Normalize the supplied address — the structured 'addressLine1'/'addressLine2' when
194	        // present, otherwise the flat 'address' — storing the normalized form (and the composed
195	        // 'address') back on the DTO so it is what gets persisted and compared. Reject the create
196	        // when no address is supplied in either form (see normalizeAddresses).
197	        if (!normalizeAddresses(ownerFieldsDto)) {
198	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
199	        }
200	        // Reject the create when the owner's city is already at capacity, i.e. it already
201	        // contains 50 or more owners (compared case-insensitively).
202	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
203	            return new ResponseEntity<>(HttpStatus.CONFLICT);
204	        }
205	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
206	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
207	        if (normalizedTelephone == null) {
208	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
209	        }
210	        ownerFieldsDto.setTelephone(normalizedTelephone);
211	        // Consolidated duplicate detection. All former separate telephone, email and household
212	        // duplicate checks are now expressed through the single derived identity key
213	        // '<normalizedTelephone>|<email or empty>|<householdId>' (see OwnerMapper#identityKey).
214	        // A create is rejected only when the new owner's identity collides with an existing owner's.
215	        // Because the telephone is part of the identity, two members of the same household with
216	        // different telephones no longer collide and are both allowed; only owners that share the
217	        // same normalized telephone and email are treated as the same identity.
218	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
219	        String contactIdentity = identityContact(candidate);
220	        boolean identityInUse = this.clinicService.findAllOwners().stream()
221	            .filter(existing -> !existing.isDeleted())
222	            .anyMatch(existing -> contactIdentity.equals(identityContact(existing)));
223	        if (identityInUse) {
224	            return new ResponseEntity<>(HttpStatus.CONFLICT);
225	        }
226	        // Household duplicate detection keyed on the deterministic householdId, derived from the
227	        // normalized last name and postcode (see OwnerMapper#householdId). Owners sharing a last
228	        // name and postcode share the same household. A second owner in an existing household is
229	        // rejected as a household duplicate (409) unless the request declares 'sharesHousehold',
230	        // in which case it is created as a declared household member — 'sharesHousehold' only
231	        // bypasses this block; the household link itself now follows from the computed householdId.
232	        String householdId = ownerMapper.householdId(candidate);
233	        boolean householdExists = this.clinicService.findAllOwners().stream()
234	            .filter(existing -> !existing.isDeleted())
235	            .anyMatch(existing -> householdId.equals(ownerMapper.householdId(existing)));
236	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
237	        if (householdExists && !sharesHousehold) {
238	            return new ResponseEntity<>(HttpStatus.CONFLICT);
239	        }
240	        boolean declaredMember = householdExists && sharesHousehold;
241	        // Determine the effective registration date — the value supplied on the request, or the
242	        // server's current date when none was supplied — and roll it forward to the next business
243	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
244	        // registration date (membership-number year segment, per-day create-limit) uses this
245	        // adjusted date.
246	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
247	        if (registrationDate == null) {
248	            registrationDate = LocalDate.now();
249	        }
250	        // Reject a supplied registration date that lies in the future (later than the
251	        // server's current date): an owner cannot be registered ahead of time.
252	        else if (registrationDate.isAfter(LocalDate.now())) {
253	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
254	        }
255	        registrationDate = toBusinessDay(registrationDate);
256	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
257	        // owners have already been registered on this (adjusted) business day.
258	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
259	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
260	        }
261	        HttpHeaders headers = new HttpHeaders();
262	        Owner owner = candidate;
263	        owner.setRegistrationDate(registrationDate);
264	        // Assign the customer code as '<REGION>-<HASH8>': the region derived from the owner's
265	        // postcode (falling back to the city, then 'UNKNOWN') and the first 8 upper-case hex
266	        // characters of the SHA-256 of the normalized telephone concatenated with the last name.
267	        owner.setCustomerCode(customerCode(owner));
268	        // Record how many existing owners already share this owner's first and last name
269	        // (compared case-insensitively) at the moment before this owner is created.
270	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
271	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
272	        // registered on this (adjusted) business day before this owner is created.
273	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
274	        // Record the size of this owner's household after this create: the number of existing
275	        // owners sharing the same household (i.e. the same computed householdId) plus this owner.
276	        owner.setHouseholdSize(countHouseholdMembers(owner) + 1);
277	        // Flag a possible (soft) duplicate: this owner is not a hard identity duplicate, but it
278	        // shares an existing owner's last name (case-insensitively) and postcode while carrying a
279	        // different telephone. When such a match exists, record it as 'possibleDuplicate' with
280	        // 'possibleDuplicateOf' set to the matching owner's id; otherwise it is not a possible
281	        // duplicate. A declared household member is an acknowledged member, not a suspected
282	        // duplicate, so it is never flagged.
283	        if (declaredMember) {
284	            owner.setPossibleDuplicate(false);
285	            owner.setPossibleDuplicateOf(null);
286	        }
287	        else {
288	            Owner softMatch = findPossibleDuplicate(owner);
289	            owner.setPossibleDuplicate(softMatch != null);
290	            owner.setPossibleDuplicateOf(softMatch == null ? null : softMatch.getId());
291	        }
292	        this.clinicService.saveOwner(owner);
293	        // Emit an audit line recording the new owner's id, customer code, registration date,
294	        // membership level and membership number.
295	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
296	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
297	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
298	        // Remember this create against its idempotency key so a later repeat returns the same
299	        // owner instead of creating a duplicate.
300	        if (idempotencyKey != null) {
301	            idempotentCreates.put(idempotencyKey, owner.getId());
302	        }
303	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
304	        headers.setLocation(UriComponentsBuilder.newInstance()
305	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
306	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
307	    }
308	
309	    /**
310	     * The non-blank {@code Idempotency-Key} header of the current request, or {@code null} when
311	     * absent, blank, or there is no bound request.
312	     */
313	    private static String currentIdempotencyKey() {
314	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
315	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
316	            return null;
317	        }
318	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
319	        return (key == null || key.isBlank()) ? null : key;
320	    }
321	
322	    /**
323	     * Validate and normalize the optional owner email in place.
324	     *
325	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
326	     * When present it must be a syntactically valid address; a valid address is
327	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
328	     * present but syntactically invalid, so the caller can reject with 400.
329	     */
330	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
331	        String email = ownerFieldsDto.getEmail();
332	        if (email == null || email.isBlank()) {
333	            ownerFieldsDto.setEmail(null);
334	            return true;
335	        }
336	        String normalized = email.trim().toLowerCase(Locale.ROOT);
337	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
338	            return false;
339	        }
340	        // Reject addresses whose domain is on the disposable-domain blocklist.
341	        String domain = normalized.substring(normalized.indexOf('@') + 1);
342	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
343	            return false;
344	        }
345	        ownerFieldsDto.setEmail(normalized);
346	        return true;
347	    }
348	
349	    /**
350	     * Validate the optional owner postcode in place.
351	     *
352	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
353	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
354	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
355	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
356	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
357	     * when a postcode is present but malformed or out of range, so the caller can
358	     * reject with 400.
359	     */
360	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
361	        String postcode = ownerFieldsDto.getPostcode();
362	        if (postcode == null || postcode.isBlank()) {
363	            ownerFieldsDto.setPostcode(null);
364	            return true;
365	        }
366	        if (!postcode.matches("\\d{4}")) {
367	            return false;
368	        }
369	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
370	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
371	        if (range != null) {
372	            int value = Integer.parseInt(postcode);
373	            if (value < range[0] || value > range[1]) {
374	                return false;
375	            }
376	        }
377	        return true;
378	    }
379	
380	    /**
381	     * Validate and normalize the owner's address fields in place, preferring the structured
382	     * form over the flat 'address' for backward compatibility.
383	     *
384	     * <p>When a non-blank {@code addressLine1} is supplied it is the structured form: both
385	     * {@code addressLine1} and (when present) {@code addressLine2} are normalized and stored
386	     * back, and {@code address} is set to the composed value — the normalized addressLine1,
387	     * with a single space and the normalized addressLine2 appended when addressLine2 is present.
388	     * Otherwise the flat {@code address} is normalized in place and the structured lines are
389	     * cleared. Returns {@code false} when no address is supplied in either form (both the
390	     * structured addressLine1 and the flat address are blank once normalized), so the caller
391	     * can reject with 400.
392	     */
393	    private boolean normalizeAddresses(OwnerFieldsDto ownerFieldsDto) {
394	        String rawLine1 = ownerFieldsDto.getAddressLine1();
395	        if (rawLine1 != null && !rawLine1.isBlank()) {
396	            String line1 = normalizeAddress(rawLine1);
397	            if (line1.isBlank()) {
398	                return false;
399	            }
400	            ownerFieldsDto.setAddressLine1(line1);
401	            String rawLine2 = ownerFieldsDto.getAddressLine2();
402	            String composed = line1;
403	            if (rawLine2 != null && !rawLine2.isBlank()) {
404	                String line2 = normalizeAddress(rawLine2);
405	                ownerFieldsDto.setAddressLine2(line2);
406	                composed = line1 + " " + line2;
407	            }
408	            else {
409	                ownerFieldsDto.setAddressLine2(null);
410	            }
411	            ownerFieldsDto.setAddress(composed);
412	            return true;
413	        }
414	        // No structured address: fall back to the flat 'address' input.
415	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
416	        if (canonicalAddress.isBlank()) {
417	            return false;
418	        }
419	        ownerFieldsDto.setAddress(canonicalAddress);
420	        ownerFieldsDto.setAddressLine1(null);
421	        ownerFieldsDto.setAddressLine2(null);
422	        return true;
423	    }
424	
425	    /**
426	     * Normalize an owner address: trim, collapse each run of whitespace to a single
427	     * space, upper-case, and expand common street-type abbreviations
428	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
429	     * A {@code null} value normalizes to the empty string.
430	     */
431	    private static String normalizeAddress(String value) {
432	        if (value == null) {
433	            return "";
434	        }
435	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
436	        if (collapsed.isEmpty()) {
437	            return "";
438	        }
439	        String[] tokens = collapsed.split(" ");
440	        StringBuilder sb = new StringBuilder(collapsed.length());
441	        for (int i = 0; i < tokens.length; i++) {
442	            if (i > 0) {
443	                sb.append(' ');
444	            }
445	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
446	        }
447	        return sb.toString();
448	    }
449	
450	    /**
451	     * The contact portion of an owner's derived identity key: its normalized telephone and
452	     * email ('&lt;normalizedTelephone&gt;|&lt;email or empty&gt;'), i.e. the identity key
453	     * without the household segment. Two owners share an identity when this value is equal;
454	     * because the telephone is part of it, members of one household with different telephones
455	     * do not collide. A {@code null} email contributes the empty string.
456	     */
457	    private static String identityContact(Owner owner) {
458	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
459	        String email = owner.getEmail() == null ? "" : owner.getEmail();
460	        return telephone + "|" + email;
461	    }
462	
463	    /**
464	     * Normalize a telephone number to E.164 form.
465	     *
466	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
467	     * explicit leading {@code '+'} and country code it is kept; otherwise the
468	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
469	     * dropped from the national digits. The result must contain 8 to 15 digits
470	     * after the {@code '+'}, and — for a recognised country calling code — exactly
471	     * the national-number length that code mandates ({@code '+61'} => 9 national
472	     * digits, {@code '+1'} => 10).
473	     *
474	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
475	     *         the input is absent or cannot form a valid E.164 number.
476	     */
477	    private static String toE164(String raw) {
478	        if (raw == null) {
479	            return null;
480	        }
481	        String trimmed = raw.trim();
482	        boolean hasCountryCode = trimmed.startsWith("+");
483	        // Strip spaces, dashes and brackets.
484	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
485	        String digits;
486	        if (hasCountryCode) {
487	            // Keep the explicit country code; drop the leading '+' for validation.
488	            digits = stripped.substring(1);
489	        } else {
490	            // No country code: assume '+61' and drop a single leading '0'.
491	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
492	            digits = "61" + national;
493	        }
494	        if (!digits.matches("\\d{8,15}")) {
495	            return null;
496	        }
497	        // For a recognised country calling code, enforce the exact national-number length it
498	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
499	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
500	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
501	                .sorted((a, b) -> b.length() - a.length()).toList()) {
502	            if (digits.startsWith(countryCode)) {
503	                int nationalLength = digits.length() - countryCode.length();
504	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
505	                    return null;
506	                }
507	                break;
508	            }
509	        }
510	        return "+" + digits;
511	    }
512	
513	    /**
514	     * Count the existing owners whose first and last name match the given names,
515	     * compared case-insensitively. Used to record an owner's namesake count at the
516	     * moment before it is created.
517	     */
518	    private int countNamesakes(String firstName, String lastName) {
519	        return (int) this.clinicService.findAllOwners().stream()
520	            .filter(existing -> existing.getFirstName() != null
521	                && existing.getFirstName().equalsIgnoreCase(firstName)
522	                && existing.getLastName() != null
523	                && existing.getLastName().equalsIgnoreCase(lastName))
524	            .count();
525	    }
526	
527	    /**
528	     * Count the existing owners in the same household as the given owner, i.e. those sharing its
529	     * computed householdId (derived from the normalized last name and postcode). Used, together
530	     * with the owner being created, to derive the household size recorded on the owner.
531	     */
532	    private int countHouseholdMembers(Owner owner) {
533	        String householdId = ownerMapper.householdId(owner);
534	        return (int) this.clinicService.findAllOwners().stream()
535	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
536	            .count();
537	    }
538	
539	    /**
540	     * Find an existing owner that the given (not-yet-created) owner is a possible (soft) duplicate
541	     * of: one sharing the same last name (compared case-insensitively) and the same postcode, but
542	     * carrying a different normalized telephone. Owners without a postcode never match (the postcode
543	     * must be shared). When several existing owners match, the one with the lowest id is returned so
544	     * the result is deterministic. Returns {@code null} when there is no such match.
545	     */
546	    private Owner findPossibleDuplicate(Owner candidate) {
547	        if (candidate.getPostcode() == null) {
548	            return null;
549	        }
550	        return this.clinicService.findAllOwners().stream()
551	            .filter(existing -> !existing.isDeleted())
552	            .filter(existing -> existing.getLastName() != null
553	                && existing.getLastName().equalsIgnoreCase(candidate.getLastName())
554	                && candidate.getPostcode().equals(existing.getPostcode())
555	                && !candidate.getTelephone().equals(existing.getTelephone()))
556	            .min(java.util.Comparator.comparing(Owner::getId))
557	            .orElse(null);
558	    }
559	
560	    /**
561	     * Build the owner's customer code, formatted {@code '<REGION>-<HASH8>'}.
562	     *
563	     * <p>{@code REGION} is the region derived from the owner's postcode (see
564	     * {@link #deriveRegion}). {@code HASH8} is the first 8 upper-case hex characters of the
565	     * SHA-256 of the normalized telephone concatenated with the last name
566	     * (e.g. {@code 'NSW-1A2B3C4D'}).
567	     *
568	     * <p>When the computed code collides with an existing owner's customer code, it is
569	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more
570	     * that makes it unique.
571	     */
572	    private String customerCode(Owner owner) {
573	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
574	        String hash8 = sha256HexUpper(owner.getTelephone() + owner.getLastName(), 8);
575	        String base = region + "-" + hash8;
576	        Set<String> existing = this.clinicService.findAllOwners().stream()
577	            .map(Owner::getCustomerCode)
578	            .filter(java.util.Objects::nonNull)
579	            .collect(Collectors.toSet());
580	        if (!existing.contains(base)) {
581	            return base;
582	        }
583	        int n = 2;
584	        while (existing.contains(base + "-" + n)) {
585	            n++;
586	        }
587	        return base + "-" + n;
588	    }
589	
590	    /**
591	     * Derive the owner's region, preferring the postcode. The postcode is matched against
592	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
593	     * it is absent or in no known range does this fall back to the fixed city-to-region table
594	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
595	     */
596	    private static String deriveRegion(String postcode, String city) {
597	        if (postcode != null && postcode.matches("\\d{4}")) {
598	            int value = Integer.parseInt(postcode);
599	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
600	                int[] range = entry.getValue();
601	                if (value >= range[0] && value <= range[1]) {
602	                    return entry.getKey();
603	                }
604	            }
605	        }
606	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
607	    }
608	
609	    /**
610	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
611	     * bytes of {@code value}.
612	     */
613	    private static String sha256HexUpper(String value, int length) {
614	        try {
615	            byte[] digest = MessageDigest.getInstance("SHA-256")
616	                .digest(value.getBytes(StandardCharsets.UTF_8));
617	            StringBuilder sb = new StringBuilder(digest.length * 2);
618	            for (byte b : digest) {
619	                sb.append(String.format("%02X", b));
620	            }
621	            return sb.substring(0, length);
622	        }
623	        catch (NoSuchAlgorithmException e) {
624	            throw new IllegalStateException(e);
625	        }
626	    }
627	
628	    /**
629	     * Count the existing owners located in the given city, compared case-insensitively.
630	     * Used to derive the per-city 4-digit sequence in the customer code.
631	     */
632	    private int countOwnersInCity(String city) {
633	        return (int) this.clinicService.findAllOwners().stream()
634	            .filter(existing -> existing.getCity() != null
635	                && existing.getCity().equalsIgnoreCase(city))
636	            .count();
637	    }
638	
639	    /**
640	     * Count the existing owners whose registration date is the given (adjusted business) date.
641	     * Used to enforce the per-day sign-up limit.
642	     */
643	    private int countOwnersRegisteredOn(LocalDate date) {
644	        return (int) this.clinicService.findAllOwners().stream()
645	            .filter(existing -> date.equals(existing.getRegistrationDate()))
646	            .count();
647	    }
648	
649	    /** Fixed public holidays the business-day roll skips. */
650	    private static final Set<LocalDate> HOLIDAYS = Set.of(
651	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
652	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
653	        LocalDate.parse("2026-12-28"));
654	
655	    /**
656	     * Roll a registration date forward onto a business day: a Saturday, Sunday, or listed
657	     * public holiday is moved forward to the next non-holiday weekday; a plain weekday is
658	     * returned unchanged.
659	     */
660	    private static LocalDate toBusinessDay(LocalDate date) {
661	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
662	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
663	            || HOLIDAYS.contains(date)) {
664	            date = date.plusDays(1);
665	        }
666	        return date;
667	    }
668	
669	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
670	    @Override
671	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
672	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
673	        if (currentOwner == null) {
674	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
675	        }
676	        if (!normalizeEmail(ownerFieldsDto)) {
677	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
678	        }
679	        if (!normalizePostcode(ownerFieldsDto)) {
680	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
681	        }
682	        if (!normalizeAddresses(ownerFieldsDto)) {
683	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
684	        }
685	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
686	        if (normalizedTelephone == null) {
687	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
688	        }
689	        currentOwner.setAddress(ownerFieldsDto.getAddress());
690	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
691	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
692	        currentOwner.setCity(ownerFieldsDto.getCity());
693	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
694	        currentOwner.setLastName(ownerFieldsDto.getLastName());
695	        currentOwner.setTelephone(normalizedTelephone);
696	        currentOwner.setEmail(ownerFieldsDto.getEmail());
697	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
698	        this.clinicService.saveOwner(currentOwner);
699	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
700	    }
701	
702	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
703	    @Transactional
704	    @Override
705	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
706	        Owner owner = this.clinicService.findOwnerById(ownerId);
707	        if (owner == null) {
708	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
709	        }
710	        // Soft-delete: flag the owner deleted and retain the record so it can still be
711	        // read back (with 'deleted' true) and is ignored by later duplicate/identity checks.
712	        owner.setDeleted(true);
713	        this.clinicService.saveOwner(owner);
714	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
715	    }
716	
717	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
718	    @Override
719	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
720	        Owner owner = this.clinicService.findOwnerById(ownerId);
721	        if (owner == null) {
722	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
723	        }
724	        HttpHeaders headers = new HttpHeaders();
725	        Pet pet = petMapper.toPet(petFieldsDto);
726	        owner.setId(ownerId);
727	        pet.setOwner(owner);
728	        pet.getType().setName(null);
729	        this.clinicService.savePet(pet);
730	        PetDto petDto = petMapper.toPetDto(pet);
731	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
732	            .buildAndExpand(pet.getId()).toUri());
733	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
734	    }
735	
736	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
737	    @Override
738	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
739	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
740	        if (currentOwner != null) {
741	            Pet currentPet = this.clinicService.findPetById(petId);
742	            if (currentPet != null) {
743	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
744	                currentPet.setName(petFieldsDto.getName());
745	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
746	                this.clinicService.savePet(currentPet);
747	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
748	            }
749	        }
750	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
751	    }
752	
753	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
754	    @Override
755	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
756	        HttpHeaders headers = new HttpHeaders();
757	        Visit visit = visitMapper.toVisit(visitFieldsDto);
758	        Pet pet = new Pet();
759	        pet.setId(petId);
760	        visit.setPet(pet);
761	        this.clinicService.saveVisit(visit);
762	        VisitDto visitDto = visitMapper.toVisitDto(visit);
763	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
764	            .buildAndExpand(visit.getId()).toUri());
765	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
766	    }
767	
768	
769	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
770	    @Override
771	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
772	        Owner owner = this.clinicService.findOwnerById(ownerId);
773	        if (owner != null) {
774	            Pet pet = owner.getPet(petId);
775	            if (pet != null) {
776	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
777	            }
778	        }
779	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
780	    }
781	}
